// [U10] Дословный перенос trim-логики пяти веток старого воркфлоу
function trim_credit(data) {


// 1. Умный поиск выбранной комплектации (смотрим в qualification_context)
let qc = data.qualification_context || {};
let cached = qc.cached_json || {};
let req = data.user_request || cached.user_request || {};

// Достаем ID: приоритет на прямой ключ в qualification_context
let selectedId = qc.complectation_id || req.selected_complectation_id || cached.complectation_id;
let selectedName = req.selected_complectation_name;

// 2. Ищем массив всех машин
let rawComps = [];
if (cached.complectations) {
    rawComps = cached.complectations;
} else if (data.complectations) {
    rawComps = data.complectations;
}

// 3. Чистим и ФИЛЬТРУЕМ
let cleanComplectations = [];
if (Array.isArray(rawComps)) {
    let cleaned = rawComps.map(comp => {
        let c = Object.assign({}, comp);

        // Удаляем тяжелые данные для экономии контекста (токенов)
        delete c.features;
        delete c.images;
        delete c.stock_details;
        delete c.stock_colors;
        delete c.specs;

        // Мы НЕ удаляем c.price, так как он уже содержит:
        // MSRP (Price old), cash_bonus (Cash in hook), base_price (Price new),
        // credit_price и tradein_price.

        return c;
    });

    // Если нашли конкретный ID, оставляем только эту машину
    if (selectedId) {
        cleanComplectations = cleaned.filter(comp => String(comp.id) === String(selectedId));
    } 

    // Запасной вариант по имени, если по ID ничего не нашлось
    if (cleanComplectations.length === 0 && selectedName) {
        cleanComplectations = cleaned.filter(comp => 
            comp.name === selectedName || comp.full_name === selectedName
        );
    }

    // Если всё еще пусто — отдаем весь очищенный список
    if (cleanComplectations.length === 0) {
        cleanComplectations = cleaned;
    }
}

// 4. Формируем финальный объект (Разделяем данные для промпта и контекст ИИ)
return {
    ...data,

    ai_clean_context: {
        "user_id": data.user_id || qc.user_id || "",
        "deal_id": data.deal_id || qc.deal_id || "",
        "model": data.model || qc.model || cached.model || (data.fresh_cache || {}).model || "",
        "user_data": Object.assign({}, cached.user_data || {}, data.user_data || {}),
        "user_request": req,
        "complectations": cleanComplectations // Теперь тут 5 уровней цены для каждой машины
    }
};
}

function trim_consult(input) {
// 1. Получаем входящие данные (не мутируем их, а просто читаем)


// 2. Умный поиск контекста и данных дилера
const qc = input.qualification_context || {};
const cached = qc.cached_json || {};

// 3. Берем массив всех комплектаций (без фильтрации, со всеми фото и ТТХ)
const rawComps = cached.complectations || input.complectations || [];

// 4. Очищаем только финансовый мусор и склад (фото, опции и ТТХ ОСТАВЛЯЕМ)
const cleanComps = rawComps.map(comp => {
    let c = Object.assign({}, comp);

    // В Консультанте ОСТАВЛЯЕМ блок price целиком.
    // Он уже содержит подготовленные в JavaScript1 данные:
    // MSRP, cash_bonus, base_price, credit_price, tradein_price.

    // Удаляем только расчетные блоки и данные о складских остатках
    delete c.images; // <--- ДОБАВЛЕНО
    delete c.credit_calculation;
    delete c.combo_calculation;
    delete c.stock_count;
    delete c.stock_details;
    delete c.stock_colors;

    return c;
});

// 5. ЯВНО возвращаем новый объект. Разделяем данные для промпта и контекст ИИ.
return {
    ...input, // Копируем все технические ID и маршрутизацию

    ai_clean_context: {
        "user_id": input.user_id || qc.user_id || "",
        "deal_id": input.deal_id || qc.deal_id || "",
        "model": input.model || qc.model || cached.model || (input.fresh_cache || {}).model || "",
        "user_data": Object.assign({}, cached.user_data || {}, input.user_data || {}),
        "user_request": input.user_request || cached.user_request || { payment: 0 },
        "complectations": cleanComps // Полный список с характеристиками и 5 уровнями цены
    }
};
}

function trim_stock(data) {


// 1. Ищем массив машин (умный поиск)
let rawComps = [];
if (data.qualification_context && data.qualification_context.cached_json && data.qualification_context.cached_json.complectations) {
    rawComps = data.qualification_context.cached_json.complectations;
} else if (data.complectations) {
    rawComps = data.complectations;
}

// 2. Чистим машины (Оставляем Склад и прозрачные цены за наличку)
let cleanComplectations = [];
if (Array.isArray(rawComps)) {
    cleanComplectations = rawComps.map(comp => {
        let c = Object.assign({}, comp);

        // Удаляем блоки с расчетами условий (в наличии работаем от базы)
        delete c.credit_calculation;
        delete c.combo_calculation;

        // --- ОБНОВЛЕННАЯ ЛОГИКА ЦЕН: Фокус на прозрачности ---
        if (c.price) {
            c.price = { 
                MSRP: c.price.MSRP,              // Розничная цена по прайсу
                cash_bonus: c.price.cash_bonus,  // Прямая скидка от автосалона
                base_price: c.price.base_price   // Итоговая цена за наличные
            };
            // Удаляем кредитные и трейд-ин поля, чтобы ИИ не путал клиента в этой ветке
        }

        // Удаляем тяжелые данные для экономии контекста
        delete c.images;

        return c;
    });
}

// Безопасно обнуляем payment, чтобы бот не заговорил про платежи
let cleanUserRequest = data.user_request ? Object.assign({}, data.user_request) : {};
cleanUserRequest.payment = 0;

// 3. Формируем финальный объект для ИИ (Разделяем данные для промпта и контекст ИИ)
// Аккуратно достаем user_data из кэша (если он есть), чтобы не делать длинную строку ниже
let cachedUserData = (data.qualification_context && data.qualification_context.cached_json) 
    ? data.qualification_context.cached_json.user_data 
    : {};
return {
    ...data,

    ai_clean_context: {
        "user_id": data.user_id || (data.qualification_context ? data.qualification_context.user_id : ""),
        "deal_id": data.deal_id || (data.qualification_context ? data.qualification_context.deal_id : ""),
        "dealer_id_used": data.dealer_id_used || (data.qualification_context ? data.qualification_context.dealer_id : ""),
        "model": data.model || (data.qualification_context ? data.qualification_context.model : "") || ((data.qualification_context || {}).cached_json || {}).model || (data.fresh_cache || {}).model || "",
        "user_data": Object.assign({}, cachedUserData || {}, data.user_data || {}),
        "user_request": cleanUserRequest,
        "complectations": cleanComplectations // Теперь тут только MSRP, cash_bonus и base_price
    }
};
}

function trim_tradein(data) {


// 1. Умный поиск контекста и выбранной комплектации
let qc = data.qualification_context || {};
let cached = qc.cached_json || {};
let req = data.user_request || cached.user_request || {};

// Достаем ID: приоритет на прямой ключ в qualification_context
let selectedId = qc.complectation_id || req.selected_complectation_id || cached.complectation_id;
let selectedName = req.selected_complectation_name;

// 2. Ищем массив всех машин
let rawComps = [];
if (cached.complectations) {
    rawComps = cached.complectations;
} else if (data.complectations) {
    rawComps = data.complectations;
}

// 3. Чистим машины и ФИЛЬТРУЕМ
let cleanComplectations = [];
if (Array.isArray(rawComps)) {
    let cleaned = rawComps.map(comp => {
        let c = Object.assign({}, comp);

        // --- ОБНОВЛЕННАЯ ЛОГИКА ЦЕН ДЛЯ ТРЕЙД-ИН ---
        // Оставляем все 5 уровней, но для этой ветки ИИ будет делать упор на tradein
        if (c.price) {
            c.price = { 
                MSRP: c.price.MSRP,              // Цена по прайсу
                cash_bonus: c.price.cash_bonus,  // Прямая скидка
                base_price: c.price.base_price,  // Базовая цена (MSRP - cash_bonus)
                tradein_price: c.price.tradein_price,
                tradein_bonus: c.price.tradein_bonus
            };
        }

        // Удаляем тяжелый мусор для экономии токенов
        delete c.features;
        delete c.images;
        delete c.stock_count;
        delete c.stock_details;
        delete c.stock_colors;
        delete c.credit_calculation;
        delete c.combo_calculation;
        delete c.specs;

        return c;
    });

    // ФИЛЬТРАЦИЯ
    if (selectedId) {
        cleanComplectations = cleaned.filter(comp => String(comp.id) === String(selectedId));
    } 

    if (cleanComplectations.length === 0 && selectedName) {
        cleanComplectations = cleaned.filter(comp => 
            comp.name === selectedName || comp.full_name === selectedName
        );
    }

    if (cleanComplectations.length === 0) {
        cleanComplectations = cleaned;
    }
}

// 4. Формируем контекст для ИИ (Разделяем данные для промпта и контекст ИИ)
return {
    ...data,

    ai_clean_context: {
        "user_id": data.user_id || qc.user_id || "",
        "deal_id": data.deal_id || qc.deal_id || "",
        "dealer_id_used": data.dealer_id_used || qc.dealer_id || "",
        "model": data.model || qc.model || cached.model || (data.fresh_cache || {}).model || "",
        "user_data": Object.assign({}, cached.user_data || {}, data.user_data || {}),
        "user_request": req,
        "complectations": cleanComplectations
    }
};
}

function trim_combo(data) {


// 1. Умный поиск контекста и выбранной комплектации
let qc = data.qualification_context || {};
let cached = qc.cached_json || {};
let req = data.user_request || cached.user_request || {};

// Достаем ID: приоритет на прямой ключ в qualification_context
let selectedId = qc.complectation_id || req.selected_complectation_id || cached.complectation_id;
let selectedName = req.selected_complectation_name;

// 2. Ищем массив всех машин
let rawComps = [];
if (cached.complectations) {
    rawComps = cached.complectations;
} else if (data.complectations) {
    rawComps = data.complectations;
}

// 3. Чистим машины и ФИЛЬТРУЕМ
let cleanComplectations = [];
if (Array.isArray(rawComps)) {
    let cleaned = rawComps.map(comp => {
        let c = Object.assign({}, comp);

        // В Комбо ОСТАВЛЯЕМ блок price целиком. 
        // Он уже содержит: MSRP, cash_bonus, base_price, credit_price, tradein_price.

        // Удаляем тяжелый мусор для экономии токенов
        delete c.features;
        delete c.images;
        delete c.specs;
        delete c.stock_count;
        delete c.stock_details;
        delete c.stock_colors;

        // Удаляем базовые кредитные расчеты (ИИ будет оперировать цифрами из price)
        delete c.credit_calculation;

        return c;
    });

    // ФИЛЬТРАЦИЯ: Если нашли ID, оставляем в массиве только одну машину
    if (selectedId) {
        cleanComplectations = cleaned.filter(comp => String(comp.id) === String(selectedId));
    } 

    // Если по ID не нашли, но есть имя — фильтруем по имени
    if (cleanComplectations.length === 0 && selectedName) {
        cleanComplectations = cleaned.filter(comp => 
            comp.name === selectedName || comp.full_name === selectedName
        );
    }

    // Если всё еще пусто (ничего не выбрано), отдаем весь очищенный список
    if (cleanComplectations.length === 0) {
        cleanComplectations = cleaned;
    }
}

// 4. Формируем финальный объект (Разделяем данные для промпта и контекст ИИ)
return {
    ...data,

    // Оставляем для ИИ только чистые данные по авто, клиенту и ID
    ai_clean_context: {
        "user_id": data.user_id || qc.user_id || "",
        "deal_id": data.deal_id || qc.deal_id || "",
        "dealer_id_used": data.dealer_id_used || qc.dealer_id || "",
        "model": data.model || qc.model || cached.model || (data.fresh_cache || {}).model || "",
        "user_data": Object.assign({}, cached.user_data || {}, data.user_data || {}),
        "user_request": req,
        "complectations": cleanComplectations // 5 уровней цены внутри каждой машины
    }
};
}

const item = $('Stage Classifier').first().json;
const scenario = (item.session_context || {}).request_type
    || (item.qualification_context || {}).request_type || "consult";
const fn = { credit: trim_credit, consult: trim_consult, stock: trim_stock,
             tradein: trim_tradein, combo: trim_combo }[scenario] || trim_consult;
const res = fn(Object.assign({}, item));

// [U5] Переменные личного кабинета — единой точкой, а не правкой пяти веток:
// trim-логика перенесена дословно из legacy и является гарантией паритета.
// Ключей может не быть в qualification_context ВОВСЕ (на стороне бота выдача
// токена обёрнута в try/except), поэтому || "" — он нормализует и отсутствие
// ключа, и пустое значение в одно: кабинет не упоминаем в обоих случаях.
const qcCab = item.qualification_context || {};
const cabinet = {
    cabinet_url: qcCab.cabinet_url || "",
    cabinet_status: qcCab.cabinet_status || "",
};

// [U6] Оценка трейд-ина — в контекст модели. Без этого правило «оценка уже есть,
// повторно инструмент не вызывай» неисполнимо: активные D_TRADEIN / D_COMBO прямо
// говорят «JSON — твой ЕДИНСТВЕННЫЙ источник правды», а суммы в JSON не было вовсе,
// поэтому модель обязана была звать платный evaluate_auto заново на каждом
// возврате к цифрам. Источники — те же, что у U3, в том же приоритете.
// Госномер и пробег отданы вместе с суммой: без них «повторный вызов только при
// смене номера или пробега» модели не на чем проверить.
const evalSrc = qcCab.evaluation_carryover || {};
const cachedCab = qcCab.cached_json || {};
const tiValue = Number(evalSrc.ti_valuation) > 0 ? Number(evalSrc.ti_valuation)
              : (Number(cachedCab.ti_valuation) > 0 ? Number(cachedCab.ti_valuation) : 0);
const tiCar = (evalSrc.found_info && evalSrc.found_info.plate) ? evalSrc.found_info
            : ((cachedCab.found_info && cachedCab.found_info.plate) ? cachedCab.found_info : null);
const evaluation = {};
if (tiValue > 0) evaluation.ti_valuation = tiValue;
if (tiCar) evaluation.ti_evaluated_car = { plate: tiCar.plate || "", mileage: tiCar.mileage || 0 };

const out = (res && res.ai_clean_context)
    ? Object.assign({}, res, {
        ai_clean_context: Object.assign({}, res.ai_clean_context, cabinet, evaluation) })
    : res;
return [{ json: Object.assign({}, out) }];

const item = $input.first().json;
const turn = item.turn;
const sc = item.session_context || {};
const scenario = sc.request_type || (item.qualification_context || {}).request_type || "consult";
const up = scenario.toUpperCase();
const stage = turn.stage;
const intent = turn.intent;

